import pathlib,json,subprocess
root=pathlib.Path.cwd()
values=[]
for path in (root/'.runtime').rglob('*.env'):
    for line in path.read_text().splitlines():
        if '=' in line:
            k,v=line.split('=',1)
            if any(t in k for t in ('PASSWORD','SECRET','API_KEY')) and len(v)>=16:values.append(v.encode())
state=json.loads((root/'.runtime/recovery/run-01/worker/state.json').read_text())
for user in state['users']:
    for k in ('email','password','user_id','access_token','refresh_token','new_access_token','new_refresh_token'):
        if user.get(k):values.append(user[k].encode())
values.append((root/'.runtime/recovery-keys/run-01/bundle.key').read_bytes())
names=subprocess.run(['git','diff','--cached','--name-only','-z'],capture_output=True,check=True).stdout.decode().strip('\x00').split('\x00')
leaks=[]
for name in names:
    body=subprocess.run(['git','show',':'+name],capture_output=True,check=True).stdout
    if any(value in body for value in values):leaks.append(name)
assert not leaks,'Known private values found in staged paths: '+repr(leaks)
print(json.dumps({'staged_files_checked':len(names),'known_private_value_scan_passed':True,'private_values_printed':False}))
